+    int half = K / 2;
+    int base = (b * H + h) * L;
+
+    float acc = 0.0f;
+    for (int j = 0; j < K; ++j) {
+        int xi = t + j - half;
+        if (xi >= 0 && xi < L) {
+            acc += x[base + xi] * k[h * K + j];
+        }
+    }
