+    while (active > 1) {
+        int next = (active + 1) / 2;
+        if (tid < active - next) {
+            #pragma unroll
+            for (int q = 0; q < 4; ++q) {
+                partial[q][tid] += partial[q][tid + next];
+            }
+        }
